<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { Plus, Send, MessageSquare, Sparkles, Trash2, Pencil } from 'lucide-vue-next';
import { studio, startGeneration, blankAttributes } from '@/services/studio';
import { uid, now } from '@/services/storage';
import { toast } from 'vue-sonner';
const props=defineProps<{projectId:string}>();const route=useRoute();const router=useRouter();const input=ref('');const search=ref('');const fail=ref(false);const deleting=ref('');const editTitle=ref('');const renameId=ref('');const seconds=ref('15');const ratio=ref('9:16');const outputType=ref<'视频'|'图文'>('视频');
const sessions=computed(()=>studio.value.sessions.filter(s=>s.projectId===props.projectId&&s.title.toLowerCase().includes(search.value.toLowerCase())));
const current=computed(()=>studio.value.sessions.find(s=>s.id===route.query.session&&s.projectId===props.projectId));
const directions=['问题开场 · 用痛点抓住注意力','对比实测 · 让变化自己说话','生活叙事 · 让产品自然入镜'];
function select(id:string){void router.replace({query:{...route.query,session:id}});}
function create(){const reference=studio.value.references.find(r=>r.id===route.query.reference);const product=studio.value.products.find(p=>p.id===route.query.product);const session={id:uid(),projectId:props.projectId,title:reference?`复刻 · ${reference.title}`:'新的创作会话',stage:0,brief:'',direction:'',script:'',version:1,messages:[{role:'assistant' as const,text:'你好，我是你的创作搭档。请告诉我：想推广什么产品？面向谁？希望表达什么？我会陪你从创意到脚本，一步步完成成片。'}],updatedAt:now(),reference,productIds:product?[product.id]:[]};studio.value.sessions.unshift(session);select(session.id);}
watch(()=>current.value?.id,()=>{input.value='';seconds.value=current.value?.duration??'15';ratio.value=current.value?.ratio??'9:16';outputType.value=current.value?.outputType??'视频';},{immediate:true});
watch([seconds,ratio,outputType],()=>{const s=current.value;if(s){s.duration=seconds.value;s.ratio=ratio.value;s.outputType=outputType.value;s.updatedAt=now();}});
function productChanged(){const s=current.value;if(s&&s.stage>1){s.stage=1;s.direction='';s.script='';s.version++;s.updatedAt=now();s.messages.push({role:'assistant',text:'产品卡已变更，请重新确认创意方向与脚本。旧成片作为历史版本保留。'});}}
function chat(){const s=current.value;if(!s||!input.value.trim())return;const text=input.value.trim();s.messages.push({role:'user',text});if(s.stage>1){s.stage=1;s.direction='';s.script='';s.version++;s.messages.push({role:'assistant',text:'需求已更新，原有成片保留为历史版本。请重新选择创意方向，确认新的脚本后再生成。'});}else{s.stage=1;s.messages.push({role:'assistant',text:'收到。我已整理你的需求，请从下方选择一个创意方向，也可以继续告诉我调整意见。'});}s.brief += `${s.brief?'\n':''}${text}`;s.title=s.title==='新的创作会话'?text.slice(0,24):s.title;s.updatedAt=now();input.value='';}
function choose(direction:string){const s=current.value;if(!s)return;s.direction=direction;s.stage=2;s.script=`【开场 0–3 秒】\n${direction.split(' · ')[0]}，以产品特写引出需求。\n\n【展开 3–10 秒】\n结合「${s.brief.slice(0,80)}」展现使用场景与核心卖点。\n\n【收尾 10–15 秒】\n展示使用结果与品牌画面，以自然的行动邀请结束。`;s.messages.push({role:'assistant',text:`已选择「${direction}」。下方脚本与分镜可以直接编辑，确认后进入生成设置。`});s.updatedAt=now();}
function scriptChanged(){const s=current.value;if(s&&s.stage>2){s.stage=2;s.version++;}}
function generate(){const s=current.value;if(!s)return;if(!s.script.trim()){toast.error('请先填写脚本');return;}if(studio.value.projects.find(p=>p.id===props.projectId)?.archived){toast.error('归档项目不能生成');return;}if(studio.value.jobs.some(j=>j.sessionId===s.id&&['生成中','等待中'].includes(j.status))){toast.info('当前会话正在生成');return;}startGeneration({projectId:props.projectId,sessionId:s.id,title:`${s.title} · V${s.version}`,type:outputType.value,source:'专家创作',duration:seconds.value,ratio:ratio.value,quality:'1080P',brief:s.script,reference:s.reference,productIds:[...s.productIds],version:s.version,mediaIds:[],inPublishing:false,attributes:{...blankAttributes(),theme:s.title,hook:s.direction.split(' · ')[0]!,product:studio.value.products.find(p=>p.id===s.productIds[0])?.name??'未分类'}},fail.value);s.stage=4;s.messages.push({role:'assistant',text:'生成任务已提交。进度与结果显示在下方，离开页面后也会保留。'});s.updatedAt=now();}
</script>
<template><div class="flex min-h-[560px] overflow-hidden rounded-2xl border border-slate-200"><div class="flex min-w-0 flex-1 flex-col bg-slate-50/40"><div class="flex items-center gap-2 border-b border-slate-100 bg-white px-5 py-4"><Sparkles class="h-4 w-4 text-sky-500" /><span class="text-sm font-semibold">{{current?.title??'专家创作工作台'}}</span><span class="ml-auto text-[11px] text-slate-400">{{current?`版本 ${current.version}`:'你的 AI 创作搭档'}}</span></div><template v-if="current"><div class="flex flex-wrap gap-2 px-5 pt-4"><span v-for="(label,i) in ['需求澄清','创意方向','脚本分镜','生成确认','成片结果']" :key="label" class="rounded-full px-3 py-1.5 text-[11px]" :class="current.stage===i?'bg-sky-100 text-sky-700':'bg-white text-slate-400'">{{i+1}} · {{label}}</span></div><div class="max-h-[360px] space-y-4 overflow-y-auto p-5"><div v-if="current.reference" class="rounded-lg border border-sky-100 bg-sky-50 p-3 text-xs text-sky-600">参考：{{current.reference.title}}</div><div v-for="(m,i) in current.messages" :key="i" class="flex" :class="m.role==='user'?'justify-end':''"><div class="max-w-[90%] whitespace-pre-wrap rounded-2xl px-4 py-3 text-[13px] leading-6" :class="m.role==='user'?'bg-sky-500 text-white':'border border-slate-100 bg-white text-slate-600'">{{m.text}}</div></div></div><div class="space-y-4 px-5 pb-5"><div v-if="current.stage===1" class="space-y-2"><button v-for="d in directions" :key="d" class="w-full rounded-xl border border-sky-100 bg-white px-4 py-3 text-left text-xs text-sky-700 hover:bg-sky-50" @click="choose(d)">{{d}} →</button></div><div v-if="current.stage>=2" class="studio-card"><div class="mb-3 flex justify-between text-xs"><span class="font-semibold">脚本与分镜 · {{current.direction}}</span><span class="text-slate-400">{{current.stage===2?'待确认':'已确认'}}</span></div><textarea v-model="current.script" aria-label="脚本与分镜" class="studio-field h-52 py-3 text-xs leading-6" @input="scriptChanged" /><button v-if="current.stage===2" class="studio-primary mt-3" @click="current.stage=3">确认脚本，进入生成</button><div v-else class="mt-4 space-y-3"><div class="grid grid-cols-3 gap-3"><label><span class="studio-label">类型</span><select v-model="outputType" class="studio-field"><option>视频</option><option>图文</option></select></label><label><span class="studio-label">画幅</span><select v-model="ratio" class="studio-field"><option>9:16</option><option>16:9</option><option>1:1</option></select></label><label><span class="studio-label">时长</span><select v-model="seconds" class="studio-field"><option value="15">15 秒</option><option value="30">30 秒</option><option value="60">60 秒</option></select></label></div><label class="block text-[11px] text-slate-400"><input v-model="fail" type="checkbox">模拟生成失败（可重试）</label><div class="flex items-center gap-3"><button class="studio-primary" @click="generate">{{current.stage===4?'再次生成':'确认并生成'}} · 预计 20 积分</button><button class="text-xs text-slate-400" @click="current.stage=2">返回修改脚本</button></div><p class="text-[10px] text-slate-400">原型不实际扣费，生成结果为可预览的创作方案。</p></div></div><label class="block"><span class="studio-label">关联产品卡</span><select v-model="current.productIds" multiple class="studio-field h-20 py-2" aria-label="关联产品卡" @change="productChanged"><option v-for="p in studio.products.filter(p=>p.projectId===projectId)" :key="p.id" :value="p.id">{{p.name||'未命名产品'}}</option></select></label><form class="flex items-end gap-2 rounded-xl border border-slate-200 bg-white p-2" @submit.prevent="chat"><textarea v-model="input" aria-label="专家对话" class="min-h-16 flex-1 resize-none p-2 text-[13px] outline-none" placeholder="描述需求，或告诉我你希望怎样调整…" @keydown.ctrl.enter="chat" /><button class="studio-primary !px-3" :disabled="!input.trim()"><Send class="h-4 w-4" /></button></form></div></template><div v-else class="flex flex-1 flex-col items-center justify-center p-10"><MessageSquare class="mb-5 h-10 w-10 text-sky-300" /><h3 class="text-xl font-semibold text-slate-700">好创意，从对话开始</h3><p class="my-4 text-sm leading-7 text-slate-400">需求澄清 → 创意选择 → 脚本确认 → 生成成片</p><button class="studio-primary" @click="create"><Plus class="h-4 w-4" />新建会话</button></div></div><aside class="w-52 shrink-0 border-l border-slate-100 bg-white p-3 xl:w-60"><button class="studio-btn w-full" @click="create"><Plus class="h-4 w-4" />新建会话</button><input v-model="search" class="studio-field my-3 !h-8 text-xs" placeholder="搜索历史会话"><div class="mb-3 px-2 text-[11px] text-slate-400">历史会话 · 当前项目</div><div v-for="s in sessions" :key="s.id" class="group mb-2 rounded-xl p-3" :class="s.id===current?.id?'bg-sky-50':'hover:bg-slate-50'"><button class="w-full truncate text-left text-xs text-slate-700" @click="select(s.id)">{{s.title}}</button><div class="mt-2 flex items-center gap-2 text-[10px] text-slate-400"><span class="flex-1">{{new Date(s.updatedAt).toLocaleDateString()}}</span><button aria-label="重命名会话" @click="renameId=s.id;editTitle=s.title"><Pencil class="h-3 w-3" /></button><button aria-label="删除会话" @click="deleting=s.id"><Trash2 class="h-3 w-3" /></button></div><div v-if="renameId===s.id" class="mt-2"><input v-model="editTitle" class="studio-field !h-8" @keydown.enter="s.title=editTitle.trim()||s.title;renameId='' "><button class="mt-2 text-xs text-sky-600" @click="s.title=editTitle.trim()||s.title;renameId=''">保存名称</button></div><div v-if="deleting===s.id" class="mt-2 text-xs"><p class="mb-2 text-rose-500">删除此会话？成片仍保留。</p><button class="mr-3 text-rose-500" @click="studio.sessions=studio.sessions.filter(x=>x.id!==s.id);deleting=''">删除</button><button @click="deleting=''">取消</button></div></div><p v-if="!sessions.length" class="px-2 py-8 text-center text-xs text-slate-400">暂无历史会话</p></aside></div></template>
